def bars(pre,vals,names,unit,x0=120,base=400,bw=60,gap=30,top=110,cols=(BL,OR,GR,PU,RD)):
    """vertical bar chart: bars b{pre}{k}, value labels v{pre}{k}, names n{pre}{k}; unit = pixels per 1 unit of value"""
    LN(pre+"ax",x0-20,base,x0+len(vals)*(bw+gap),base,"#16253F",5); LN(pre+"ay",x0-20,base,x0-20,top,"#16253F",5)
    for k,v in enumerate(vals):
        x=x0+k*(bw+gap); h=max(2,v*unit)
        RECT(f"b{pre}{k}",x,base-h,bw,h,"#BBDEFB" if k%2==0 else "#FFE0B2",cols[k%5],3)
        L(str(v),f"v{pre}{k}",y=base-h-10,s=24,c="#16253F",x=x+bw/2); L(names[k],f"n{pre}{k}",y=base+30,s=20,c="#455A64",x=x+bw/2)
